<?php
class PlanillaEstadoModel{private $db;function __construct(PDO $db){$this->db=$db;}function aprobar(int $id,int $usuario):void{$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT estado FROM periodos_pago WHERE id_periodo_pago=? FOR UPDATE');$q->execute([$id]);if($q->fetchColumn()!=='CALCULADO')throw new RuntimeException('Solo se puede aprobar una planilla calculada.');$q=$this->db->prepare('SELECT COUNT(*) FROM planilla_detalles WHERE id_periodo_pago=?');$q->execute([$id]);if((int)$q->fetchColumn()<1)throw new RuntimeException('La planilla no tiene trabajadores calculados.');$this->db->prepare("UPDATE periodos_pago SET estado='REVISADO',revisado_por=?,revisado_en=NOW() WHERE id_periodo_pago=?")->execute([$usuario,$id]);$this->db->prepare("UPDATE planilla_detalles SET estado='REVISADO' WHERE id_periodo_pago=?")->execute([$id]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}function cerrar(int $id,int $usuario):void{$this->db->beginTransaction();try{$q=$this->db->prepare('SELECT estado FROM periodos_pago WHERE id_periodo_pago=? FOR UPDATE');$q->execute([$id]);if($q->fetchColumn()!=='REVISADO')throw new RuntimeException('La planilla debe estar revisada antes de cerrarla.');$this->db->prepare("UPDATE periodos_pago SET estado='CERRADO',cerrado_por=?,cerrado_en=NOW() WHERE id_periodo_pago=?")->execute([$usuario,$id]);$this->db->prepare("UPDATE planilla_detalles SET estado='CERRADO' WHERE id_periodo_pago=?")->execute([$id]);$this->db->commit();}catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();throw$e;}}}
